// Toggle Menu
$(document).ready(function(){
    			
	$('#navi-icon').click( function(){
		if ( $(this).hasClass('closed') ){
			$(this).removeClass( 'closed' ).addClass( 'opened' );
			$('#fullwidth_menu').removeClass( 'closed' ).addClass( 'opened' );
			$('#fullwidth_menu').slideDown( 300 );
			$('.site-header').addClass( 'menu-opened' );
			$('#top-area').removeClass('fadein');
			$('.section-navi').removeClass('slipup');
		} else {
			$(this).removeClass( 'opened' ).addClass( 'closed' );
			$('#fullwidth_menu').removeClass( 'opened' ).addClass( 'closed' );
			$('#fullwidth_menu').slideUp( 300 );
			$('.site-header').removeClass( 'menu-opened' );
			$('#top-area').addClass('fadein');
			$('.section-navi').addClass('slipup');
		};
	} );
	
});


