/** Close others <details> tag */
$(document).ready(function(){
	const allDetails = document.querySelectorAll("details")

	allDetails.forEach((details) => {
		details.addEventListener("toggle", (e) => {
			if (details.open) {
				allDetails.forEach((details) => {
					if (details != e.target && details.open) {
						details.open = false
					}
				})
			}
		})
	})
});


// Header Scroll
$(window).scroll (function () {
	var sT = $(this).scrollTop();
		if (sT > 0) {
			$('.site-header').addClass('cambio_header');			
			$('.section-status').addClass('scroll-snap');
			$('.section-navi').addClass('scroll-snap');
		} else {
			$('.site-header').removeClass('cambio_header');			
			$('.section-status').removeClass('scroll-snap');
			$('.section-navi').removeClass('scroll-snap');		
		};
});

// Pageheader Scroll
$(window).scroll (function () {
	var sT = $(this).scrollTop();
	var cutHeight = 0;
	var profileInfoSectionH = $("#profileInfoSection").height();
	if(typeof profileInfoSectionH != "undefined") {
		cutHeight += profileInfoSectionH;
	}
	
	var tourInfoMenuSectionH = $("#tourInfoMenuSection").height();
	if(typeof tourInfoMenuSectionH != "undefined") {
		cutHeight += tourInfoMenuSectionH;
	}
	
	if (sT > cutHeight) {
		$('.section-pagemenu').addClass('cambio_header');
		if($(".section-pageheader").hasClass("scroll-snap") === true) {
			$('.section-pageheader.scroll-snap').addClass('cambio_header');
			$('.section-pagemenu').addClass('margin_before');
		}
	} else {
		$('.section-pagemenu').removeClass('cambio_header');
		$('.section-pagemenu').removeClass('margin_before');
		$('.section-pageheader.scroll-snap').removeClass('cambio_header');
	};
});

